import { prepareWalletReceipt } from '../app/wallet-receipt.js';
import { boxReference } from './box-queue.js';
import { hasWalletIds, hasCompactBoxQueue } from './schema.js';
import { lootboxSession, inLootboxSession, pendingBoxWord } from './recycling.js';
import { eventFacts, eventPage, eventOrdinal, plainEvent, eventCatalog } from './facts.js';
import { contractInterface, ChainDataError, checkAbort, decodeLog, compareLogs } from './client.js';
import { playerAddress, uint } from './state.js';
import { decorateWalletRows } from './wallet-events.js';
import { decodeBoxScoreCode } from '../app/box-queue-rolls.js';

// Audit 4f4aa8377 removed the presale. Degenesis results share the box-results feed under the
// database's vocabulary (rewardType 'degenesis_opened', legType 'degenesis'); they are cohort
// orders with no lootboxIndex and never open-anchor a Luckbox.
// PresaleBoxOpened / PresaleBoxBuy stay readable on archived deployments; every list is filtered to
// the active schema's events (knownEvents) so neither name is requested where it does not exist.
export const BOX_RESULTS = ['LootBoxOpened', 'DegenesisOrderResolved', 'PresaleBoxOpened', 'LootBoxDgnrsBatch', 'LootBoxWhalePassJackpot', 'LootBoxReward', 'LootBoxCrapsPasses', 'BoxSpin'];
const RESULT_TYPES = { LootBoxOpened: 'opened', DegenesisOrderResolved: 'degenesis_opened', PresaleBoxOpened: 'presale_opened' };
const LEG_TYPES = { LootBoxOpened: 'opened', DegenesisOrderResolved: 'degenesis', PresaleBoxOpened: 'presale', LootBoxDgnrsBatch: 'dgnrs', LootBoxWhalePassJackpot: 'whalepass', LootBoxReward: 'reward', LootBoxCrapsPasses: 'crapsPasses', BoxSpin: 'spin' };
export async function knownEvents(names) {
  const known = new Set((await eventCatalog()).filter(row => row.contract === 'GAME').map(row => row.event.name));
  return names.filter(name => known.has(name));
}
const meta = row => ({ blockNumber: String(row.blockNumber), transactionHash: row.transactionHash, logIndex: row.logIndex });

export async function gameReceipt(s, hash, signal, blockHash) {
  if (!s.gameReceipts) s.gameReceipts = new Map();
  if (s.gameReceipts.has(hash)) return s.gameReceipts.get(hash);
  const pending = decodeGameReceipt(s, hash, signal, blockHash); s.gameReceipts.set(hash, pending);
  try { return await pending; } catch(error) { s.gameReceipts.delete(hash); throw error; }
}
async function decodeGameReceipt(s, hash, signal, blockHash) {
  const receipt = await s.client.receipt(hash, signal, blockHash); const iface = await contractInterface('GAME');
  const rows = receipt.logs.filter(log => log.address.toLowerCase() === s.client.address('GAME')).flatMap(log => {
    let parsed; try { parsed = decodeLog(iface, log); } catch { return []; }
    return parsed ? [plainEvent({ ...log, args: parsed.args }, parsed.fragment)] : [];
  });
  // Run 66: wallet-ID fields also carry their address under the old name (wallet-events.js).
  return decorateWalletRows(s, 'GAME', rows);
}
export async function boxLeg(s, row, { receipt, signal } = {}) {
  const a = row.args; const player = a.player;
  const events = receipt ?? await gameReceipt(s, row.transactionHash, signal, row.blockHash);
  // Counted boxes settle several legs in one transaction. The shared order
  // index is common to a player's opening anchors, never a unique box id.
  const anchors = events.filter(e => e.args.player === player && ['LootBoxOpened', 'PresaleBoxOpened'].includes(e.name));
  const indices = new Set(anchors.map(e => Number(e.args.lootboxIndex ?? e.args.index)));
  const ownIndex = a.lootboxIndex ?? (row.name === 'PresaleBoxOpened' ? a.index : null);
  let lootboxIndex = row.name === 'DegenesisOrderResolved' ? null
    : ownIndex != null ? Number(ownIndex) : indices.size === 1 ? [...indices][0] : null;
  if (lootboxIndex == null && row.name === 'BoxSpin') {
    // Spin-only boxes have no LootBoxOpened anchor. A direct openBox call
    // supplies the exact index without guessing from unrelated receipt legs.
    const tx = await s.client.rpc('eth_getTransactionByHash', [row.transactionHash], signal);
    if (tx?.to?.toLowerCase() === s.client.address('GAME')) {
      const decoded = (await contractInterface('GAME')).parseTransaction({ data: tx.input });
      if (decoded?.name === 'openBox' && decoded.args[0].toLowerCase() === player) lootboxIndex = Number(decoded.args[1]);
    }
  }
  const delivery = events.find(e => e.name === 'AfkingDelivered' && e.args.player === player);
  let spin = null;
  if (row.name === 'BoxSpin') {
    const { decodeBoxSpin } = await import('../app/lootbox-legs.js');
    spin = { ...decodeBoxSpin(a.betId, a.packedSpins), payout: a.payout, ethShare: a.ethShare };
  }
  return { uid: `${row.transactionHash}:${row.logIndex}`, source: spin ? 'spin' : 'result', legType: LEG_TYPES[row.name],
    rewardType: RESULT_TYPES[row.name] ?? row.name, player, lootboxIndex, origin: lootboxIndex == null ? null : delivery ? 'afking' : 'normal',
    boxAmountRawWei: a.lootboxAmount ?? (['LootBoxOpened', 'PresaleBoxOpened'].includes(row.name) ? a.amount : null),
    afkingSpendRawWei: delivery ? String(BigInt(delivery.args.packed) & ((1n << 128n) - 1n)) : null,
    levelAtOpen: null, rewardData: spin ? null : a, spin, ...meta(row), ord: eventOrdinal(row) };
}

export async function degeneretteItem(s, row, signal) {
  // Audit 224de529: a bet is (index, betId) — betId is its queue position + 1
  // WITHIN the index — and it settles automatically on the keeper sweep. One
  // DegeneretteResolved (all three keys indexed) carries every spin.
  const a = row.args; const player = a.player; const betId = a.betId; const index = a.index;
  const deg = await import('../app/degenerette.js');
  const [session, resolvedRows] = await Promise.all([
    lootboxSession(s, index, { fromBlock: row.blockNumber, afterLogIndex: row.logIndex, signal }),
    eventFacts(s, ['DegeneretteResolved'], { contract: 'GAME', player, filters: { index, betId }, fromBlock: row.blockNumber, afterLogIndex: row.logIndex, signal }),
  ]);
  const word = session.word;
  const resolved = resolvedRows.find(event => inLootboxSession(event, session, row)) ?? null;
  const bet = deg.decodeDegeneretteBetWord(a.packed);
  let spinRows = []; let payouts = [];
  if (resolved) {
    spinRows = deg.degeneretteSpinResults({ ...resolved.args }, a.packed) ?? [];
    // A keeper sweep settles every bet at an index (many owners) after opening
    // that index's boxes, in ONE transaction. Only this bet's own contiguous
    // window — its direct Luckbox before the settlement, its record BoxSpin
    // after — belongs to it.
    const [receipt, events] = await Promise.all([
      s.client.receipt(resolved.transactionHash, signal, resolved.blockHash),
      gameReceipt(s, resolved.transactionHash, signal, resolved.blockHash),
    ]);
    await prepareWalletReceipt(receipt, s.client);
    const narrowed = deg.degeneretteSettlementReceipt(receipt, { player, index, betId, packedData: a.packed, game: s.client.address('GAME') });
    const own = new Set((narrowed?.logs ?? []).map(log => Number(log.logIndex ?? log.index)));
    payouts = events.filter(e => e.args.player === player && BOX_RESULTS.includes(e.name) && own.has(Number(e.logIndex)));
  }
  // The biggest-spin claim waits in degeneretteRecordBounty only until the bet
  // settles; the placement receipt's Coinflip BigRecordUpdated keeps it.
  let recordStake = null;
  if (bet?.recordArmed) {
    try {
      const placement = await s.client.receipt(row.transactionHash, signal, row.blockHash);
      await prepareWalletReceipt(placement, s.client);
      const stake = deg.parseRecordStakeFromReceipt(placement, player, { coinflip: s.client.address('COINFLIP') });
      recordStake = stake > 0n ? String(stake) : null;
    } catch (error) { if (error?.name === 'AbortError') throw error; }
  }
  const spinCount = spinRows.length || bet?.spinCount || null;
  return { id: eventOrdinal(row), player, betIndex: Number(index), betId, packedData: a.packed, ...meta(row),
    rngReady: word !== 0n, rngWord: word ? String(word) : null, recordStake,
    // totalPayout is in the bet's currency (whole FLIP on chain since audit b05ea7c50); token wei here.
    results: resolved ? [
      { resultType: 'resolved', payout: String(deg.degeneretteTotalPayoutFromChain(resolved.args.totalPayout, a.packed)),
        resultData: { ...resolved.args, totalPayout: String(deg.degeneretteTotalPayoutFromChain(resolved.args.totalPayout, a.packed)), spinCount }, ...meta(resolved) },
      // Per-spin payouts are not emitted; they are the module's own payout math
      // over the emitted score/wilds and the bet word's stake and activity.
      ...spinRows.map(r => ({ resultType: 'result', payout: String(r.payout), ...meta(resolved), resultData: {
        player, index: String(index), betId: String(betId), spinIndex: String(r.spinIndex), playerTraits: String(r.playerTraits),
        matches: String(r.matches), ...(hasWalletIds() ? { wilds: String(r.wilds) } : { goldMatches: String(r.goldMatches) }), payout: String(r.payout) } })),
    ] : [],
    // The shared presentation code derives and checks every reel from the RNG
    // word against the emitted score and spin-zero result.
    resultTickets: [], activityBps: bet ? bet.activityScore : null, activityBreakdown: null,
    lootboxPayouts: payouts.map(e => ({ rewardType: RESULT_TYPES[e.name] ?? e.name, rewardData: e.args, lootboxIndex: e.args.lootboxIndex == null ? null : Number(e.args.lootboxIndex), ...meta(e) })) };
}

export async function readFeedRoute(s, url, { signal } = {}) {
  const path = url.pathname; const q = url.searchParams;
  if (path === '/degenesis/orders') return degenesisOrders(s, q.has('player') ? playerAddress(q.get('player')) : null, signal);
  if (!['/lootbox/feed', '/lootbox/legs', '/lootbox/box-spins', '/degenerette/feed'].includes(path)) return undefined;
  const player = q.has('player') ? playerAddress(q.get('player')) : undefined;
  const names = path === '/degenerette/feed' ? ['DegeneretteBetPlaced'] : path === '/lootbox/feed' ? await knownEvents(['LootBoxBuy', 'PresaleBoxBuy'])
    : path === '/lootbox/box-spins' ? ['BoxSpin'] : await knownEvents(BOX_RESULTS);
  const page = await eventPage(s, names, url, { contract: 'GAME', player, signal });
  if (path === '/lootbox/feed' && player && q.has('recover')) {
    const { pendingBoxes } = await import('./pending.js');
    const pending = await pendingBoxes(s, player, signal);
    page.rows = [...new Map([...page.rows, ...pending].map(row => [eventOrdinal(row), row])).values()];
  }
  const items = [];
  for (const row of page.rows) {
    checkAbort(signal);
    if (path === '/degenerette/feed') { items.push(await degeneretteItem(s, row, signal)); continue; }
    if (path === '/lootbox/legs' || path === '/lootbox/box-spins') {
      const leg = await boxLeg(s, row, { signal });
      if (q.has('lootboxIndex') && leg.lootboxIndex !== uint(q.get('lootboxIndex'), Number.MAX_SAFE_INTEGER)) continue;
      items.push(path === '/lootbox/box-spins' ? { id: leg.ord, player: leg.player, ...leg.spin, ...meta(row) } : leg); continue;
    }
    const a = row.args; const buyer = a.buyer; const ref = boxReference(a.index, a.position);
    const [session, pending, openedRows, receipt] = await Promise.all([
      lootboxSession(s, a.index, { fromBlock: row.blockNumber, afterLogIndex: row.logIndex, signal }),
      pendingBoxWord(s, row.name === 'PresaleBoxBuy' ? 'presaleBoxEth' : 'lootboxOrder', a.index, buyer, a.position),
      eventFacts(s, await knownEvents(['LootBoxOpened', 'PresaleBoxOpened']), { contract: 'GAME', player: buyer, filters: { lootboxIndex: ref, index: ref }, fromBlock: row.blockNumber, afterLogIndex: row.logIndex, signal }),
      gameReceipt(s, row.transactionHash, signal, row.blockHash),
    ]);
    const boost = receipt.find(e => e.name === 'LootBoxBoostConsumed' && e.args.player === buyer);
    items.push({ id: eventOrdinal(row), player: buyer, kind: 'eth', costRawWei: a.amount,
      boxAmountRawWei: boost?.args.boostedAmount ?? a.amount, boostBps: boost ? Number(boost.args.boostBps) : null,
      resolvedIndex: Number(ref), ...meta(row), rngReady: session.word !== 0n, opened: session.next !== null || (!hasWalletIds() && openedRows.some(e => inLootboxSession(e, session, row))) || (session.word !== 0n && pending === 0n),
      // Compact (§2/§4): the 12-bit score code at bit 53 decodes to whole points (exact through
      // 2,042). Runs 66-74 stored the raw score at bit 56; earlier runs at bit 24.
      activityBps: pending ? Number(!hasWalletIds() ? (pending >> 24n) & 0x7fffn
        : hasCompactBoxQueue() ? decodeBoxScoreCode((pending >> 53n) & 0xfffn) : (pending >> 56n) & 0x7fffn) : null, activityBreakdown: null,
      results: openedRows.filter(e => inLootboxSession(e, session, row)).map(e => ({ rewardType: RESULT_TYPES[e.name], rewardData: e.args, blockNumber: String(e.blockNumber), levelAtOpen: null })) });
  }
  return { items, nextCursor: page.nextCursor };
}

/**
 * One player's Degenesis orders: every DegenesisBuy (cohort day 1-7, zero-based order index) joined
 * with its DegenesisOrderResolved, newest first. `resolved` is null while the cohort is unsettled
 * (sealed at its day's end, bound to a later daily word, then mined in chunks).
 */
export async function degenesisOrders(s, player, signal) {
  if (!player) throw new ChainDataError('Choose a player.', 'INVALID_REQUEST');
  const known = new Set((await eventCatalog()).map(row => row.event.name));
  if (!known.has('DegenesisBuy')) return { items: [], supported: false };
  const rows = await eventFacts(s, ['DegenesisBuy', 'DegenesisOrderResolved'], { contract: 'GAME', player, signal });
  const key = a => `${Number(a.degenesisDay)}:${Number(a.orderIndex)}`;
  const resolved = new Map(rows.filter(row => row.name === 'DegenesisOrderResolved').map(row => [key(row.args), row]));
  const items = rows.filter(row => row.name === 'DegenesisBuy').map(row => {
    const a = row.args; const r = resolved.get(key(a));
    return { player, degenesisDay: Number(a.degenesisDay), orderIndex: Number(a.orderIndex), amountRawWei: String(a.amount),
      secondsIntoDay: Number(a.secondsIntoDay), ...meta(row), ord: eventOrdinal(row),
      resolved: r ? { flip: String(r.args.flip), dgnrs: String(r.args.dgnrs), wwxrp: String(r.args.wwxrp),
        normalPasses: Number(r.args.normalPasses), highPasses: Number(r.args.highPasses), ...meta(r) } : null };
  }).sort((x, y) => y.ord - x.ord);
  return { items, supported: true };
}
